  if (String(input?.confirmation || "") !== "DELETE_CUSTOMER") { const error = new Error("confirmation_required"); error.status = 400; error.fields = ["confirmation"]; throw error; }
  if (!env.DB) { const index = memoryCustomers.findIndex(item => Number(item.id) === id); if (index < 0) { const error = new Error("customer_not_found"); error.status = 404; throw error; } const [deleted] = memoryCustomers.splice(index, 1); return { deleted_id: id, name: deleted.name }; }
  const record = await env.DB.prepare("SELECT id,name,phone FROM customers WHERE id=? LIMIT 1").bind(id).first();
  if (!record) { const error = new Error("customer_not_found"); error.status = 404; throw error; }
