async function updateCustomerStage(env,input) {
  const phone=String(input?.phone||"").slice(0,40), stage=String(input?.stage||"Yeni talep").slice(0,40);
  const allowed=["Yeni talep","Görüşüldü","İlan gönderildi","Gösterim","Teklif"];
  if(!allowed.includes(stage))return {error:"invalid_stage"};
  if(!env.DB){const customer=memoryCustomers.find(item=>normalizePhone(item.phone)===normalizePhone(phone));if(!customer)return {error:"customer_not_found"};const from=customer.stage||"Yeni talep";customer.stage=stage;customer.last="Şimdi";customer.next=stage==="Teklif"?"Teklif takibi":stage==="Gösterim"?"Gösterim teyidi":"Sonraki adımı planla";if(from!==stage)memoryStageEvents.push({customer_id:Number(customer.id)||null,from_stage:from,to_stage:stage,changed_at:new Date().toISOString()});return customer}
  const existing=await findCustomerByPhone(env,phone);
  if(!existing)return {error:"customer_not_found"};
  const next=stage==="Teklif"?"Teklif takibi":stage==="Gösterim"?"Gösterim teyidi":"Sonraki adımı planla";
  if(String(existing.stage||"Yeni talep")!==stage){
    const changedAt=new Date().toISOString();
    const results=await env.DB.batch([
      env.DB.prepare("UPDATE customers SET stage=?,last_contact=?,next_step=? WHERE id=?").bind(stage,"Şimdi",next,existing.id),
      env.DB.prepare("INSERT INTO customer_stage_events (customer_id,from_stage,to_stage,changed_at) SELECT id,?,?,? FROM customers WHERE id=? AND stage=?").bind(String(existing.stage||"Yeni talep"),stage,changedAt,existing.id,stage),
    ]);
    if(!results?.[0]?.meta?.changes)return {error:"customer_not_found"};
  }else await env.DB.prepare("UPDATE customers SET stage=?,last_contact=?,next_step=? WHERE id=?").bind(stage,"Şimdi",next,existing.id).run();
  return {phone,stage};
}
