async function recordAudit(env, input) {
  const event = {
    actor: String(input?.actor || "ui").slice(0, 40),
    action: String(input?.action || "change").slice(0, 60),
    entity: String(input?.entity || "system").slice(0, 60),
    entity_id: String(input?.entity_id || "").slice(0, 120),
    summary: String(input?.summary || "İşlem kaydı").replace(/[\r\n]+/g, " ").slice(0, 240),
    result: String(input?.result || "success").slice(0, 30),
    model: String(input?.model || "unspecified").slice(0, 80),
    effort: ["light","medium","high"].includes(input?.effort) ? input.effort : "light",
    run_id: String(input?.run_id || "").replace(/[^a-zA-Z0-9._:-]/g, "").slice(0, 80),
  };
  if (!env.DB) { memoryAuditEvents.unshift({...event, created_at: "Şimdi"}); memoryAuditEvents.splice(100); return; }
  try {
    await env.DB.prepare("INSERT INTO audit_events (actor,action,entity,entity_id,summary,result,model,effort,run_id) VALUES (?,?,?,?,?,?,?,?,?)").bind(event.actor,event.action,event.entity,event.entity_id,event.summary,event.result,event.model,event.effort,event.run_id).run();
  } catch (_) {}
}
async function recordAuditFailure(env, input) {
  return recordAudit(env, {...input, result: "error"});
}
async function listAuditEvents(env, filters = {}) {
  const limit = Math.min(100, Math.max(1, Number(filters.limit) || 100));
  const allowed = value => String(value || "").trim().slice(0, 60);
  const entity = allowed(filters.entity), action = allowed(filters.action), resultFilter = allowed(filters.result), runId = String(filters.run_id || "").replace(/[^a-zA-Z0-9._:-]/g, "").slice(0, 80);
  if (!env.DB) return memoryAuditEvents.filter(event => (!entity || event.entity === entity) && (!action || event.action === action) && (!resultFilter || event.result === resultFilter) && (!runId || event.run_id === runId)).slice(0, limit);
  const where = [], values = [];
  if (entity) { where.push("entity=?"); values.push(entity); }
  if (action) { where.push("action=?"); values.push(action); }
  if (resultFilter) { where.push("result=?"); values.push(resultFilter); }
  if (runId) { where.push("run_id=?"); values.push(runId); }
  const query = `SELECT id,actor,action,entity,entity_id,summary,result,model,effort,run_id,created_at FROM audit_events ${where.length ? `WHERE ${where.join(" AND ")}` : ""} ORDER BY id DESC LIMIT ${limit}`;
  const result = await env.DB.prepare(query).bind(...values).all();
  return result.results || [];
}
async function summarizeAuditEvents(env) {
  if (!env.DB) {
    const byResult = {}, byEntity = {};
    for (const event of memoryAuditEvents) { byResult[event.result] = (byResult[event.result] || 0) + 1; byEntity[event.entity] = (byEntity[event.entity] || 0) + 1; }
    return { total: memoryAuditEvents.length, by_result: byResult, by_entity: byEntity, latest_at: memoryAuditEvents[0]?.created_at || null };
  }
  const [totalResult, resultRows, entityRows, latest] = await Promise.all([
    env.DB.prepare("SELECT COUNT(*) AS total FROM audit_events").first(),
    env.DB.prepare("SELECT result,COUNT(*) AS count FROM audit_events GROUP BY result ORDER BY count DESC").all(),
    env.DB.prepare("SELECT entity,COUNT(*) AS count FROM audit_events GROUP BY entity ORDER BY count DESC").all(),
    env.DB.prepare("SELECT created_at FROM audit_events ORDER BY id DESC LIMIT 1").first(),
  ]);
  return {
    total: Number(totalResult?.total || 0),
    by_result: Object.fromEntries((resultRows?.results || []).map(row => [row.result, Number(row.count)])),
    by_entity: Object.fromEntries((entityRows?.results || []).map(row => [row.entity, Number(row.count)])),
    latest_at: latest?.created_at || null,
  };
}
async function getSystemHealth(env) {
  const health = { status: "degraded", database_ready: false, audit_ready: false, audit_schema_ready: false, relationship_schema_ready: false, source_review_schema_ready: false, listing_review_schema_ready: false, listing_preferences_schema_ready: false, saved_listing_filters_schema_ready: false, stage_history_schema_ready: false, task_priority_schema_ready: false, task_timezone_schema_ready: false, audit_columns: [], relationship_columns: [], whatsapp_automatic_sending: false };
  if (!env.DB) return health;
  try { await env.DB.prepare("SELECT 1 FROM customers LIMIT 1").first(); health.database_ready = true; } catch (_) {}
  try { await env.DB.prepare("SELECT 1 FROM audit_events LIMIT 1").first(); health.audit_ready = true; } catch (_) {}
  try {
    const columns = await env.DB.prepare("PRAGMA table_info(audit_events)").all();
    health.audit_columns = (columns.results || []).map(column => column.name).filter(Boolean);
    health.audit_schema_ready = ["model", "effort", "run_id"].every(column => health.audit_columns.includes(column));
  } catch (_) {}
  try {
    const tables = await Promise.all(["activities","tasks","whatsapp_messages"].map(table => env.DB.prepare(`PRAGMA table_info(${table})`).all()));
    health.relationship_columns = tables.map((result,index)=>({table:["activities","tasks","whatsapp_messages"][index],columns:(result.results||[]).map(column=>column.name).filter(Boolean)}));
    health.relationship_schema_ready = health.relationship_columns.every(table=>table.columns.includes("customer_id"));
  } catch (_) {}
  try { const columns=await env.DB.prepare("PRAGMA table_info(customers)").all();health.source_review_schema_ready=(columns.results||[]).some(column=>column.name==="source_reviewed_at"); } catch (_) {}
  try { await env.DB.prepare("SELECT listing_url,reviewed_at FROM listing_source_reviews LIMIT 1").first();health.listing_review_schema_ready=true; } catch (_) {}
  try { await env.DB.prepare("SELECT listing_url,decision,updated_at FROM listing_preferences LIMIT 1").first();health.listing_preferences_schema_ready=true; } catch (_) {}
  try { await env.DB.prepare("SELECT id,name,query,created_at FROM saved_listing_filters LIMIT 1").first();health.saved_listing_filters_schema_ready=true; } catch (_) {}
  try { await env.DB.prepare("SELECT id,customer_id,from_stage,to_stage,changed_at FROM customer_stage_events LIMIT 1").first();health.stage_history_schema_ready=true; } catch (_) {}
  try { const columns=await env.DB.prepare("PRAGMA table_info(tasks)").all();health.task_priority_schema_ready=(columns.results||[]).some(column=>column.name==="priority"); } catch (_) {}
  try { const columns=await env.DB.prepare("PRAGMA table_info(tasks)").all();health.task_timezone_schema_ready=(columns.results||[]).some(column=>column.name==="timezone"); } catch (_) {}
  health.status = health.database_ready && health.audit_ready && health.audit_schema_ready && health.relationship_schema_ready && health.source_review_schema_ready && health.listing_review_schema_ready && health.listing_preferences_schema_ready && health.saved_listing_filters_schema_ready && health.stage_history_schema_ready && health.task_priority_schema_ready && health.task_timezone_schema_ready ? "ready" : "degraded";
  return health;
}
