async function setListingPreference(env,input) {
  const rawUrl=String(input?.url||"").trim();
  const listingUrl=rawUrl.length<=500?normalizeExternalUrl(rawUrl):"";
  const decision=String(input?.decision||"");
  const fields=[];
  if(!listingUrl)fields.push("url");
  if(!["favorite","rejected","none"].includes(decision))fields.push("decision");
  if(fields.length)invalidPayload([...new Set(fields)]);
  if(decision==="none"){
    await env.DB.prepare("DELETE FROM listing_preferences WHERE listing_url=?").bind(listingUrl).run();
    return {url:listingUrl,decision:"none"};
  }
  await env.DB.prepare("INSERT INTO listing_preferences (listing_url,decision,updated_at) VALUES (?,?,?) ON CONFLICT(listing_url) DO UPDATE SET decision=excluded.decision,updated_at=excluded.updated_at").bind(listingUrl,decision,new Date().toISOString()).run();
  return {url:listingUrl,decision};
}
