async function addSavedListingFilter(env,input) {
  const name=String(input?.name||"").trim();
  const query=String(input?.query||"").trim();
  const fields=[];
  if(name.length<2||name.length>40)fields.push("name");
  if(query.length<2||query.length>100)fields.push("query");
  if(fields.length)invalidPayload(fields);
  const count=await env.DB.prepare("SELECT COUNT(*) AS count FROM saved_listing_filters").first();
  if(Number(count?.count||0)>=25){const error=new Error("saved_filter_limit");error.status=409;throw error}
  try{
    const result=await env.DB.prepare("INSERT INTO saved_listing_filters (name,query) VALUES (?,?)").bind(name,query).run();
    return {id:Number(result.meta?.last_row_id)||null,name,query};
  }catch(error){
    const duplicate=await env.DB.prepare("SELECT id,name,query FROM saved_listing_filters WHERE name=? LIMIT 1").bind(name).first();
    if(duplicate){const conflict=new Error("saved_filter_name_exists");conflict.status=409;throw conflict}
    throw error;
  }
}
async function deleteSavedListingFilter(env,input) {
  const id=Number(input?.id);
  if(!Number.isInteger(id)||id<=0)invalidPayload(["id"]);
  if(String(input?.confirmation||"")!=="DELETE_SAVED_FILTER")invalidPayload(["confirmation"]);
  const result=await env.DB.prepare("DELETE FROM saved_listing_filters WHERE id=?").bind(id).run();
  if(!result.meta?.changes)return {error:"saved_filter_not_found"};
  return {id,deleted:true};
}
