        window.showListingLocationEditor=function(title,url){let modal=document.getElementById('listingLocationModal');if(!modal){modal=document.createElement('div');modal.id='listingLocationModal';modal.className='modal-wrap';document.body.appendChild(modal)}const box=document.createElement('div');box.className='modal';const heading=document.createElement('h2');heading.textContent='İlan konumu';const label=document.createElement('label');label.textContent=String(title||'İlan');const input=document.createElement('input');input.id='listingLocationInput';input.placeholder='Doğrulanmış mahalle / mevki';const save=document.createElement('button');save.className='btn primary';save.textContent='Konumu kaydet';const cancel=document.createElement('button');cancel.className='btn ghost';cancel.textContent='Vazgeç';cancel.onclick=()=>modal.classList.remove('open');save.onclick=async()=>{const area=input.value.trim();if(!area){toast('Doğrulanmış konum gerekli.');return}save.disabled=true;try{await api('/api/listings/location',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({url,area})});const item=(typeof listings!=='undefined'?listings:[]).find(row=>row.url===url);if(item)item.area=area;modal.classList.remove('open');toast('Konum doğrulanarak kaydedildi.');window.renderListings?.();window.dispatchEvent(new Event('trio:data-changed'))}catch(error){toast('Konum kaydedilemedi.')}finally{save.disabled=false}};box.replaceChildren(heading,label,input,cancel,save);modal.replaceChildren(box);modal.classList.add('open')};
