    const healthCardScript = `<script>(function(){async function refresh(){const card=document.getElementById('systemHealthCard');if(!card||typeof api!=='function')return;try{const [health,summary]=await Promise.all([api('/api/health'),api('/api/audit/summary')]);const ready=health.status==='ready';card.innerHTML='<div class="card-head"><div><h2>Sistem durumu</h2><small>Salt-okunur altyapı kontrolü</small></div><span class="pill '+(ready?'':'orange')+'">'+(ready?'Hazır':'Kontrol gerekli')+'</span></div><div class="task"><div><b>Veritabanı</b><p>'+ (health.database_ready?'Hazır':'Kontrol gerekli') +'</p></div><span class="due">'+(health.audit_schema_ready?'Audit şeması hazır':'Şema kontrolü gerekli')+' • Müşteri bağları: '+(health.relationship_schema_ready?'Hazır':'Kontrol gerekli')+' • Müşteri kaynak incelemesi: '+(health.source_review_schema_ready?'Hazır':'Kontrol gerekli')+' • İlan kaynak incelemesi: '+(health.listing_review_schema_ready?'Hazır':'Kontrol gerekli')+' • Görev önceliği: '+(health.task_priority_schema_ready?'Hazır':'Kontrol gerekli')+' • Görev saat dilimi: '+(health.task_timezone_schema_ready?'Hazır':'Kontrol gerekli')+' • İlan tercihleri: '+(health.listing_preferences_schema_ready?'Hazır':'Kontrol gerekli')+' • Kayıtlı ilan filtreleri: '+(health.saved_listing_filters_schema_ready?'Hazır':'Kontrol gerekli')+' • Aşama geçmişi: '+(health.stage_history_schema_ready?'Hazır':'Kontrol gerekli')+'</span></div><div class="task"><div><b>Audit kayıtları</b><p>'+summary.total+' toplam kayıt • '+(summary.by_result?.error||0)+' hata</p></div><span class="due">WhatsApp otomatik: Kapalı</span></div>'}catch(error){card.innerHTML='<div class="notice" style="margin:0">Sistem durumu alınamadı.</div>'}}function mount(){const reports=document.getElementById('reports');if(!reports)return;let card=document.getElementById('systemHealthCard');if(!card){card=document.createElement('div');card.id='systemHealthCard';card.className='card';card.style.marginTop='18px';reports.appendChild(card)}refresh()}setTimeout(mount,0);setInterval(()=>{if(document.getElementById('reports')?.classList.contains('active'))refresh()},60000)})();</script></body>`;
    const insightsCardScript = `<script>(function(){async function refresh(){const card=document.getElementById('insightsSystemHealth');if(!card||typeof api!=='function')return;try{const [health,summary]=await Promise.all([api('/api/health'),api('/api/audit/summary')]);const ready=health.status==='ready';card.innerHTML='<div class="card-head"><div><h2>Sistem durumu</h2><small>Salt-okunur altyapı kontrolü</small></div><span class="pill '+(ready?'':'orange')+'">'+(ready?'Hazır':'Kontrol gerekli')+'</span></div><p class="sub">Veritabanı: '+(health.database_ready?'Hazır':'Kontrol gerekli')+' • Audit şeması: '+(health.audit_schema_ready?'Hazır':'Kontrol gerekli')+' • '+summary.total+' audit kaydı</p>'}catch(error){card.innerHTML='<div class="notice" style="margin:0">Sistem durumu alınamadı.</div>'}}function mount(){const insights=document.getElementById('insights');if(!insights)return;let card=document.getElementById('insightsSystemHealth');if(!card){card=document.createElement('div');card.id='insightsSystemHealth';card.className='card';card.style.marginTop='18px';insights.appendChild(card)}refresh()}setTimeout(mount,0);setInterval(()=>{if(document.getElementById('insights')?.classList.contains('active'))refresh()},60000)})();</script></body>`;
