    const liveDataGateScript = `<script>(function(){const gate=document.getElementById('trioLiveDataGate');const message=gate?.querySelector('[data-gate-message]');const retry=gate?.querySelector('[data-gate-retry]');if(!gate||!message||!retry)return;async function load(){document.documentElement.classList.add('trio-live-data-loading');message.textContent='Canlı Trio verileri yükleniyor…';retry.hidden=true;try{const requests=Promise.all(['/api/customers','/api/listings','/api/tasks'].map(async path=>{const response=await fetch(path,{cache:'no-store'});if(!response.ok)throw new Error('live_data_unavailable');return response.json()}));const timeout=new Promise((_,reject)=>setTimeout(()=>reject(new Error('live_data_timeout')),15000));const [customerRows,listingRows,taskRows]=await Promise.race([requests,timeout]);customers.splice(0,customers.length,...customerRows);listings.splice(0,listings.length,...listingRows);window.__trioTasks=taskRows;try{localStorage.setItem('trio_customers',JSON.stringify(customers))}catch(error){}renderCustomers();renderTasks(taskRows);renderListings();fillImportCustomers();window.dispatchEvent(new Event('trio:data-changed'));try{refreshReports()}catch(_){}try{refreshCalendar()}catch(_){};document.documentElement.classList.remove('trio-live-data-loading');gate.remove();Promise.resolve().then(()=>syncActivities()).catch(()=>{})}catch(error){message.textContent='Canlı veriler şu an alınamadı. Örnek kayıtlar gösterilmedi; bağlantı hazır olduğunda tekrar deneyin.';retry.hidden=false}}retry.addEventListener('click',load);window.__trioInitialDataLoad=load()})();</script></body>`;
    const whatsappReviewScript = `<script>(function(){const style=document.createElement('style');style.id='trio-whatsapp-review-v1';style.textContent='.trio-message-review{display:flex;align-items:center;gap:8px;margin-top:8px}.trio-message-review button{padding:7px 10px;border:1px solid #d8e5dc;border-radius:8px;background:#f5faf6;color:#1e5b47;font-size:11px;font-weight:700}.trio-message-review button:disabled{opacity:.6}.trio-message-review span{font-size:10px;color:#65766c}.trio-wa-pending{display:inline-flex;margin-left:6px;padding:2px 6px;border-radius:999px;background:#fff4dc;color:#825f23;font-size:9px;font-weight:800}';document.head.appendChild(style);function statusText(state){if(!state)return'WhatsApp bağlantı durumu kontrol ediliyor.';return state.server_config_ready?'Sunucu ayarları hazır; Meta webhook doğrulaması ve testi ayrıca yapılmalı.':'Meta bağlantısı beklemede; gelen mesajlar henüz alınmıyor.'}function decorate(){const section=document.getElementById('whatsapp-api');const host=document.getElementById('waApiMessages');if(!section||!host)return;const state=window.__trioWhatsAppStatus;const status=document.getElementById('waApiStatus');if(status){status.innerHTML='<b>Bağlantı:</b> '+statusText(state)+'<br><b>Otomatik gönderim:</b> Kapalı<br><small>Gelen mesajlar CRM’e yalnızca kullanıcı onayıyla aktarılır.</small>'}const rows=Array.isArray(window.__waInboxRows)?window.__waInboxRows:[];const selected=window.__waSelectedPhone||rows[0]?.from_phone;const selectedRows=rows.filter(row=>(row.from_phone||row.sender_name)===selected).sort((a,b)=>new Date(a.received_at||0)-new Date(b.received_at||0));host.querySelectorAll('.trio-bubble').forEach((bubble,index)=>{const row=selectedRows[index];if(!row||bubble.querySelector('[data-wa-review]'))return;const box=document.createElement('div');box.className='trio-message-review';const stateLabel=document.createElement('span');const processed=Number(row.processed);if(processed===0){const button=document.createElement('button');button.type='button';button.dataset.waReview=String(row.message_id||'');button.textContent='İncele ve CRM’ye aktar';button.onclick=async()=>{if(!window.confirm('Bu mesajı müşteri etkinliğine ekleyip CRM kaydını oluşturmayı veya mevcut müşteriyle ilişkilendirmeyi onaylıyor musunuz? Müşteri aşaması otomatik değiştirilmeyecek.'))return;button.disabled=true;try{const result=await api('/api/whatsapp/messages/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message_id:button.dataset.waReview,decision:'accept',confirmation:'PROCESS_WHATSAPP_MESSAGE'})});if(result?.error)throw new Error(result.error);window.toast?.('Mesaj onaylandı ve CRM’e işlendi.');await window.refreshWhatsAppApiStatus?.()}catch(error){window.toast?.(error?.message==='message_already_reviewed'?'Bu mesaj daha önce incelendi.':'Mesaj CRM’e aktarılamadı.');button.disabled=false}};box.appendChild(button);const ignore=document.createElement('button');ignore.type='button';ignore.textContent='Yoksay';ignore.onclick=async()=>{if(!window.confirm('Bu mesajı yoksaymak istediğinize emin misiniz?'))return;ignore.disabled=true;try{const result=await api('/api/whatsapp/messages/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message_id:row.message_id,decision:'ignore',confirmation:'IGNORE_WHATSAPP_MESSAGE'})});if(result?.error)throw new Error(result.error);window.toast?.('Mesaj inceleme kuyruğundan çıkarıldı.');await window.refreshWhatsAppApiStatus?.()}catch(error){window.toast?.('Mesaj yoksayılamadı.');ignore.disabled=false}};box.appendChild(ignore)}else{stateLabel.textContent=processed===1?'CRM’ye aktarıldı':'Yoksayıldı';box.appendChild(stateLabel)}bubble.appendChild(box)});host.querySelectorAll('.trio-conversation').forEach(button=>{if(button.querySelector('.trio-wa-pending'))return;const key=button.dataset.waConversation;const count=rows.filter(row=>(row.from_phone||row.sender_name)===key&&Number(row.processed)===0).length;if(count){const badge=document.createElement('span');badge.className='trio-wa-pending';badge.textContent=count+' inceleme';button.querySelector('.trio-conversation-title')?.appendChild(badge)}})}function refresh(){decorate()}const original=window.refreshWhatsAppApiStatus;if(typeof original==='function'&&!original.__trioWhatsAppReview){const wrapped=async function(){await original();refresh()};wrapped.__trioWhatsAppReview=true;window.refreshWhatsAppApiStatus=wrapped}setTimeout(()=>window.refreshWhatsAppApiStatus?.()||refresh(),350);const host=document.getElementById('waApiMessages');if(host)new MutationObserver(()=>setTimeout(decorate,0)).observe(host,{childList:true,subtree:true});const section=document.getElementById('whatsapp-api');setInterval(()=>{if(section?.classList.contains('active'))window.refreshWhatsAppApiStatus?.()},30000)})();</script></body>`;
