      const style=document.createElement('style');style.textContent='.trio-listing-pref-filters{display:flex;gap:7px;overflow-x:auto;margin:0 0 8px;padding:2px 0 8px;scrollbar-width:thin}.trio-listing-pref-filter{white-space:nowrap;border:1px solid var(--line);border-radius:999px;padding:8px 12px;background:#fff;color:var(--muted);font-size:11px;font-weight:700}.trio-listing-pref-filter[aria-pressed=true]{background:var(--green);color:#fff;border-color:var(--green)}.trio-listing-saved-filters{margin:0 0 16px;padding:11px 12px;border:1px solid var(--line);border-radius:12px;background:#fff}.trio-listing-filter-save-row{display:flex;gap:7px}.trio-listing-filter-save-row input{min-width:0;flex:1;border:1px solid var(--line);border-radius:8px;padding:9px 10px}.trio-listing-filter-save-row button{white-space:nowrap}.trio-listing-filter-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.trio-listing-filter-chip{display:flex;align-items:center;gap:4px;border:1px solid #dce8df;border-radius:999px;background:#f5faf6;color:var(--green);padding:5px 7px 5px 10px;font-size:10px;font-weight:800}.trio-listing-filter-chip button{border-radius:50%;padding:2px 6px;background:#e8efea;color:#52645a;font-size:12px}.listing-pref-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:9px}.listing-pref-actions button{min-height:38px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--green);font-size:11px;font-weight:800}.listing-pref-actions button[aria-pressed=true]{background:#e3f0e9;border-color:#bcd7c7}.listing-pref-actions button[data-decision=rejected][aria-pressed=true]{background:#faece8;border-color:#e8c5bd;color:#934638}.listing-pref-state{font-size:10px;color:var(--muted);margin-top:6px}';document.head.appendChild(style);
