      function setupFilters(){let host=section.querySelector('.trio-listing-pref-filters');if(host)return host;host=document.createElement('div');host.className='trio-listing-pref-filters';host.setAttribute('role','group');host.setAttribute('aria-label','İlan tercih filtresi');for(const [key,label] of [['all','Tüm ilanlar'],['favorite','Favoriler'],['rejected','Elenenler']]){const button=document.createElement('button');button.type='button';button.className='trio-listing-pref-filter';button.dataset.listingPrefFilter=key;button.textContent=label;button.setAttribute('aria-pressed',String(key===mode));button.onclick=()=>{mode=key;setupFilters().querySelectorAll('[data-listing-pref-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.listingPrefFilter===mode)));window.renderListings?.()};host.appendChild(button)}grid.parentElement.insertBefore(host,grid);setupSavedFilters();return host}
      function setupSavedFilters(){let host=section.querySelector('.trio-listing-saved-filters');if(host)return host;host=document.createElement('div');host.className='trio-listing-saved-filters';const row=document.createElement('div');row.className='trio-listing-filter-save-row';const name=document.createElement('input');name.type='text';name.maxLength=40;name.placeholder='Filtre adı · ör. Cunda 2+1';name.setAttribute('aria-label','Kaydedilecek ilan filtresinin adı');const save=document.createElement('button');save.type='button';save.className='icon-btn';save.textContent='Aramayı kaydet';save.onclick=async()=>{const query=String(search?.value||'').trim(),filterName=name.value.trim();if(filterName.length<2||query.length<2){window.toast?.('Filtre adı ve en az 2 karakterlik arama gerekli.');return}save.disabled=true;try{const result=await api('/api/listings/filters',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:filterName,query})});if(result.error)throw new Error(result.error);savedFilters=[result,...savedFilters.filter(item=>Number(item.id)!==Number(result.id))];name.value='';renderSavedFilters();window.toast?.('İlan araması kaydedildi.')}catch(error){window.toast?.(error?.message==='saved_filter_name_exists'?'Bu filtre adı zaten kullanılıyor.':'İlan araması kaydedilemedi.')}finally{save.disabled=false}};row.append(name,save);const chips=document.createElement('div');chips.className='trio-listing-filter-chips';chips.setAttribute('aria-label','Kaydedilen ilan aramaları');host.append(row,chips);section.querySelector('.trio-listing-pref-filters')?.insertAdjacentElement('afterend',host);renderSavedFilters();return host}
      function renderSavedFilters(){const host=section.querySelector('.trio-listing-filter-chips');if(!host)return;host.replaceChildren();for(const filter of savedFilters){const chip=document.createElement('span');chip.className='trio-listing-filter-chip';const apply=document.createElement('button');apply.type='button';apply.className='trio-listing-filter-chip';apply.textContent=filter.name;apply.title='Kaydedilen aramayı uygula: '+filter.query;apply.onclick=()=>{mode='all';setupFilters().querySelectorAll('[data-listing-pref-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.listingPrefFilter==='all')));if(search){search.value=filter.query;search.dispatchEvent(new Event('input',{bubbles:true}))}window.renderListings?.()};const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',filter.name+' kaydedilmiş filtresini sil');remove.onclick=async()=>{if(!window.confirm('“'+filter.name+'” filtresini silmek istiyor musunuz?'))return;remove.disabled=true;try{const result=await api('/api/listings/filters/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:filter.id,confirmation:'DELETE_SAVED_FILTER'})});if(result.error)throw new Error(result.error);savedFilters=savedFilters.filter(item=>Number(item.id)!==Number(filter.id));renderSavedFilters();window.toast?.('Kaydedilen filtre silindi.')}catch(error){window.toast?.('Kaydedilen filtre silinemedi.');remove.disabled=false}};chip.append(apply,remove);host.appendChild(chip)}}
      function decorate(){setupFilters();for(const card of grid.querySelectorAll('.listing')){const url=card.dataset.listingUrl||'';if(!url||card.querySelector('.listing-pref-actions'))continue;const actions=document.createElement('div');actions.className='listing-pref-actions';for(const [decision,label] of [['favorite','☆ Favori'],['rejected','Ele']]){const button=document.createElement('button');button.type='button';button.dataset.decision=decision;button.textContent=label;button.setAttribute('aria-pressed',String(preferences.get(url)===decision));button.setAttribute('aria-label',(decision==='favorite'?'Favori: ':'Ele: ')+(card.querySelector('h3')?.textContent||'ilan'));button.onclick=async()=>{const previous=preferences.get(url)||'none';const next=previous===decision?'none':decision;button.disabled=true;try{const saved=await api('/api/listings/preferences',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url,decision:next})});if(saved.error)throw new Error(saved.error);if(next==='none')preferences.delete(url);else preferences.set(url,next);window.renderListings?.();window.dispatchEvent(new Event('trio:data-changed'))}catch(error){window.toast?.('İlan tercihi kaydedilemedi.');button.disabled=false}};actions.appendChild(button)}const state=document.createElement('div');state.className='listing-pref-state';actions.appendChild(state);card.querySelector('.body')?.appendChild(actions)}
        for(const card of grid.querySelectorAll('.listing')){const decision=preferences.get(card.dataset.listingUrl||'')||'none';card.querySelectorAll('[data-decision]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.decision===decision)));const state=card.querySelector('.listing-pref-state');if(state)state.textContent=decision==='favorite'?'Favorilerinizde':decision==='rejected'?'Elenen ilan':'Henüz işaretlenmedi';card.style.display=mode==='all'||decision===mode?'':'none'}
        const filters=setupFilters();const counts={all:allListings().length,favorite:0,rejected:0};for(const row of allListings()){const decision=preferences.get(row.url||'');if(decision==='favorite')counts.favorite++;if(decision==='rejected')counts.rejected++}filters.querySelectorAll('[data-listing-pref-filter]').forEach(button=>{const key=button.dataset.listingPrefFilter;button.textContent=({all:'Tüm ilanlar',favorite:'Favoriler',rejected:'Elenenler'})[key]+' · '+counts[key]})}
      const original=window.renderListings;if(typeof original==='function'&&!original.__trioPreferences){const wrapped=function(){if(mode!=='all'&&typeof listingVisibleLimit!=='undefined'){listingVisibleLimit=allListings().length;listingSearchState=(document.getElementById('listingSearch')?.value||'').toLowerCase()}original();decorate()};wrapped.__trioPreferences=true;window.renderListings=wrapped;try{renderListings=wrapped}catch(_){}}
