        let indexHTML = "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>TRIO PRIME - Ayvalık Emlak İlanları</title>\n    <style>\n        :root {\n            --primary: #2c3e50;\n            --secondary: #3498db;\n            --accent: #e74c3c;\n            --background: #f8f9fa;\n            --text: #2c3e50;\n        }\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: var(--background); color: var(--text); line-height: 1.6; }\n        .hero { background: var(--primary); color: white; padding: 2rem; text-align: center; }\n        .hero h1 { font-size: 2.5rem; margin-bottom: 0.5rem; }\n        .hero p { opacity: 0.9; font-size: 1.1rem; }\n        .filters { background: white; padding: 1.5rem; margin: 2rem auto; max-width: 1200px; }\n        .filters div { margin-bottom: 1rem; }\n        .filters label { font-weight: bold; display: block; margin-bottom: 0.5rem; }\n        .filters select, .filters input { padding: 0.5rem; width: 100%; max-width: 300px; }\n        .filters select { cursor: pointer; }\n        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.5rem; max-width: 1200px; padding: 0 1rem; margin: 0 auto; }\n        .card { background: white; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1); overflow: hidden; transition: transform 0.2s; }\n        .card:hover { transform: translateY(-2px); }\n        .card-img { width: 100%; height: 180px; object-fit: cover; background: #ddd; }\n        .card-content { padding: 1rem; }\n        .card-price { font-weight: bold; color: var(--primary); font-size: 1.2rem; }\n        .card-meta { font-size: 0.8rem; color: #666; margin-top: 0.5rem; }\n        .empty { text-align: center; padding: 3rem; color: #666; display: none; }\n        #cnt-top { color: var(--primary); font-weight: bold; margin: 1rem 0; }\n        @media (max-width: 700px) { .grid { grid-template-columns: 1fr; } }\n    </style>\n</head>\n<body>\n    <section class=\"hero\" aria-label=\"Başlık\">\n        <h1>TRIO PRIME</h1>\n        <p class=\"sub\">Trio Emlak · Özancan Serhan · <strong>0533 378 68 94</strong> · Sıfır Halüsinasyon</p>\n        <p class=\"sub\" style=\"margin-top:.6rem;color:#a8a08a\">Ayvalık · Cunda · Altınova · Gömeç · İstanbul</p>\n    </section>\n\n    <div class=\"dashboard-tabs\" aria-label=\"Dashboard tabs\">\n        <button class=\"tab-btn active\" onclick=\"showTab('listings')\">İlanlar</button>\n        <button class=\"tab-btn\" onclick=\"showTab('customers')\">Müşteriler</button>\n        <button class=\"tab-btn\" onclick=\"showTab('tasks')\">Görevler</button>\n    </div>\n\n    <div class=\"filters\" aria-label=\"Filtreler\">\n        <div><label for=\"f-mah\">Mahalle</label>\n            <select id=\"f-mah\" onchange=\"apply()\">\n                <option>Tümü</option>\n    <option>150 Evler Mah.</option><option>Ada</option><option>Akin</option><option>Akçapınar Mh.</option><option>Ali Çetinkaya Mh.</option><option>Alibey Namık Kemal Mh.</option><option>Altin</option><option>Altınova Altınova Mh.</option><option>Altınova Mh.</option><option>Artvi̇n</option><option>Aylin</option><option>Ayli̇n</option><option>Ayvalik Ada</option><option>Ayvalik Coşkun</option><option>Ayvalik Konak</option><option>Ayvalik Özcan</option><option>Ayvalık Özkayaoğulları</option><option>Bağyüzü Mh.</option><option>Beşiktepe Mh.</option><option>Bulutçeşme Mh.</option><option>Burçin</option><option>Burçi̇n</option><option>Coşkun</option><option>Doğuş</option><option>Erdi̇n</option><option>Fethiye Mah.</option><option>Hacıveliler Mh.</option><option>Hamdibey Mah.</option><option>Jet</option><option>Karaayıt Mh.</option><option>Kozak</option><option>Küçükköy Küçükköy Mh.</option><option>Küçükköy Mh.</option><option>Merkez 150 Evler Mah.</option><option>Merkez Ali Çetinkaya Mh.</option><option>Merkez Fevzipaşa - Vehbibey Mh.</option><option>Merkez Gazi Kemal Paşa Mh.</option><option>Merkez Hayrettinpaşa Mh.</option><option>Merkez Kazım Karabekir Mh.</option><option>Merkez Sahil Kent Mah.</option><option>Merkez Sakarya Mah.</option><option>Merkez Sefa Çamlık Mh.</option><option>Merkez Yeni Mah.</option><option>Merkez Zekibey Mah.</option><option>Mithatpaşa Mh.</option><option>Murateli Mh.</option><option>Muğla Fethiye</option><option>Mümi̇n</option><option>Namık Kemal Mh.</option><option>Odaburnu Mh.</option><option>Platform</option><option>S&S</option><option>Sakarya Adapazarı</option><option>Sakarya Arifiye</option><option>Sakarya Karasu</option><option>Sakarya Kocaali</option><option>Sakarya Mah.</option><option>Tıfıllar Mh.</option><option>Varol</option><option>Yazlik</option><option>Yazlık</option><option>Yeniköy Mh.</option><option>Çakmak Mh.</option><option>Çamoba Mh.</option><option>Çanakkale Lapseki</option><option>Örs</option><option>Özkayaoğulları</option><option>Üçkabaağaç Mh.</option><option>İsmetpaşa Mh.</option><option>İstanbul</option></select></div>\n        <div><label for=\"f-oda\">Oda</label>\n            <select id=\"f-oda\" onchange=\"apply()\">\n                <option>Tümü</option>\n                <option>1+1</option>\n                <option>2+1</option>\n                <option>3+1</option>\n                <option>4+1</option>\n                <option>5+1</option>\n            </select></div>\n        <div><label for=\"f-store\">Emlak Ofisi</label>\n            <select <div class=\"filters\" aria-label=\"Filtreler\">\n        <div><label for=\"f-mah\">Mahalle</label>\n            <select id=\"f-mah\" onchange=\"apply()\">\n                <option>Tümü</option></select></div>\n\n        <div><label for=\"f-oda\">Oda</label>\n            <select id=\"f-oda\" onchange=\"apply()\">\n                <option>Tümü</option>\n                <option>1+1</option>\n                <option>2+1</option>\n                <option>3+1</option>\n                <option>4+1</option>\n                <option>5+1</option>\n            </select></div><div><label for=\"f-kaynaklar\">Tüm Kaynaklar</label>\n            <select id=\"f-kaynaklar\" onchange=\"apply()\">\n                <option>Tümü</option>\n                <option>Trio Portföyü</option>\n                <option>Sahibinden</option><option>150 Evler Mah.</option><option>Bulutçeşme Mh.</option><option>Muğla Fethiye</option><option>Sakarya Arifiye</option><option>Sakarya Karasu</option><option>Sakarya Mah.</option><option>Çanakkale Lapseki</option></select></div><div><label for=\"f-fiyat\">Maks. Fiyat (TL)</label>\n            <input id=\"f-fiyat\" type=\"number\" placeholder=\"Örn. 10000000\" oninput=\"apply()\"></div>\n        <div><label for=\"f-m2\">Min. m²</label>\n            <input id=\"f-m2\" type=\"number\" oninput=\"apply()\"></div>function apply() {\n            const mah = document.getElementById('f-mah').value;\n            const oda = document.getElementById('f-oda').value;\n            const kaynak = document.getElementById('f-kaynaklar').value;\n            const fMax = parseInt(document.getElementById('f-fiyat').value) || Infinity;\n            const m2Min = parseInt(document.getElementById('f-m2').value) || 0;\n            \n            // Known emlak ofisleri mahalle names (70 mahalle)\n            const emlakOfisiMahalleri = [\"150 Evler Mah.\", \"Ada\",\n            \n            // Source filter: sadece \"Tümü\" veya doğrudan sahibinden olanları göster\n            // Bu, listings.json'daki source field'i (1223 sahibinden + 16 mahalle) kullanır\n            function isSahibinden(c) {\n                return c.source && (c.source === 'sahibinden' || emlakOfisiMahalleri.includes(c.store || ''));\n            } \"Akin\", \"Akçapınar Mh.\", \"Ali Çetinkaya Mh.\", \"Alibey Namık Kemal Mh.\", \"Altin\", \"Altınova Altınova Mh.\", \"Altınova Mh.\", \"Artvi̇n\", \"Aylin\", \"Ayli̇n\", \"Ayvalik Ada\", \"Ayvalik Coşkun\", \"Ayvalik Konak\", \"Ayvalik Özcan\", \"Ayvalık Özkayaoğulları\", \"Bağyüzü Mh.\", \"Beşiktepe Mh.\", \"Bulutçeşme Mh.\", \"Burçin\", \"Burçi̇n\", \"Coşkun\", \"Doğuş\", \"Erdi̇n\", \"Fethiye Mah.\", \"Hacıveliler Mh.\", \"Hamdibey Mah.\", \"Jet\", \"Karaayıt Mh.\", \"Kozak\", \"Küçükköy Küçükköy Mh.\", \"Küçükköy Mh.\", \"Merkez 150 Evler Mah.\", \"Merkez Ali Çetinkaya Mh.\", \"Merkez Fevzipaşa - Vehbibey Mh.\", \"Merkez Gazi Kemal Paşa Mh.\", \"Merkez Hayrettinpaşa Mh.\", \"Merkez Kazım Karabekir Mh.\", \"Merkez Sahil Kent Mah.\", \"Merkez Sakarya Mah.\", \"Merkez Sefa Çamlık Mh.\", \"Merkez Yeni Mah.\", \"Merkez Zekibey Mah.\", \"Mithatpaşa Mh.\", \"Murateli Mh.\", \"Muğla Fethiye\", \"Mümi̇n\", \"Namık Kemal Mh.\", \"Odaburnu Mh.\", \"Platform\", \"S&S\", \"Sakarya Adapazarı\", \"Sakarya Arifiye\", \"Sakarya Karasu\", \"Sakarya Kocaali\", \"Sakarya Mah.\", \"Tıfıllar Mh.\", \"Varol\", \"Yazlik\", \"Yazlık\", \"Yeniköy Mh.\", \"Çakmak Mh.\", \"Çamoba Mh.\", \"Çanakkale Lapseki\", \"Örs\", \"Özkayaoğulları\", \"Üçkabaağaç Mh.\", \"İsmetpaşa Mh.\", \"İstanbul\"];\n            \n            // Helper: check if store indicates emlak ofisi\n            function isEmlakOfisi(c) {\n                return emlakOfisiMahalleri.includes(c.store || '');\n            }\n            \n            // Helper: check if URL is sahibinden\n            function isSahibindenUrl(c) {\n                return c.url && c.url.includes('sahibinden.com');\n            }\n            \n            const out = DATA.filter(c => {\n                // Mahalle filter\n                const mahMatch = (mah === 'Tümü' || c.loc === mah);\n                \n                // Oda filter\n                const odaMatch = (oda === 'Tümü' || c.oda === oda);\n                \n                // Kaynak (Tüm Kaynaklar) filter\n                let kaynakMatch;\n                // Kaynak filter: \"Tümü\" seçiliyse tüm listing'leri göster,\n                // aksi halde listings.json'daki source field'i kullan\n                kaynakMatch = (kaynak === 'Tümü' || c.source === 'sahibinden') && ...;\n                if (kaynak === 'Tümü') {\n                    kaynakMatch = true;\n                } else if (kaynak === 'Trio Portföyü') {\n                    // Trio portföyü: not from sahibinden AND not from emlak ofisi\n                    const urlIsSahibinden = isSahibindenUrl(c);\n                    const isOffice = isEmlakOfisi(c);\n                    const isTrioPortfoy = !urlIsSahibinden && !isOffice;\n                    kaynakMatch = isTrioPortfoy;\n                } else if (kaynak === 'Sahibinden') {\n                    // Sadece doğrudan sahibinden (satıcıdan/y Kira yıcısından) ilanlar\n                    const urlIsSahibinden = isSahibindenUrl(c);\n                    const isOffice = isEmlakOfisi(c);\n                    // Direct: sahibinden URL BUT not from emlak ofisi (store indicates office)\n                    const isDirect = urlIsSahibinden && !isOffice;\n                    // Also check title for direct indicators\n                    const title = c.title || '';\n                    const hasDirectIndicators = title.includes('sahibinden ') || title.includes('satıcı') || title.includes('karalayan') || title.includes('owner');\n                    const isDirectByTitle = hasDirectIndicators && urlIsSahibinden;\n                    kaynakMatch = isDirect || isDirectByTitle;\n                } else {\n                    // Diğer emlak ofisi filtresi - store matching\n                    // Kullanıcının istediği: \"Herhangi emlak ofisinden olmayan ilanlar\"\n                    // Yani: store NOT in the emlak ofisi list → show\n                    const isNotOffice = !isEmlakOfisi(c);\n                    kaynakMatch = isNotOffice;\n                }\n                \n                // Fiyat filter\n                const fiyatMatch = (c.pv ?? Infinity) <= fMax;\n                \n                // m2 filter\n                const m2Match = (parseInt(c.m2) || 0) >= m2Min;\n                \n                return mahMatch && odaMatch && kaynakMatch && fiyatMatch && m2Match;\n            });)\n                .then(data => {\n                    DATA = data;\n                    apply();\n                })\n                .catch(error => console.error('Failed to load listings.json:', error));\n        });\n\n        function apply() {\n            const mah = document.getElementById('f-mah').value;\n            const oda = document.getElementById('f-oda').value;\n            const store = document.getElementById('f-store').value;\n            const fMax = parseInt(document.getElementById('f-fiyat').value) || Infinity;\n            const m2Min = parseInt(document.getElementById('f-m2').value) || 0;\n            \n            const out = DATA.filter(c =>\n                (mah === 'Tümü' || c.loc === mah) &&\n                (oda === 'Tümü' || c.oda === oda) &&\n                (store === 'Tümü' || c.store === store) &&\n                (c.pv ?? Infinity) <= fMax &&\n                (parseInt(c.m2) || 0) >= m2Min\n            );\n            \n            // Render listings\n            const grid = document.getElementById('grid');\n            if (out.length === 0) {\n                grid.innerHTML = '';\n                document.getElementById('empty').style.display = 'block';\n            } else {\n                grid.innerHTML = out.map(card => `\n                    <div class=\"card\">\n                        <img class=\"card-img\" src=\"${c.image || 'https://via.placeholder.com/300x180'}\" alt=\"${c.title}\">\n                        <div class=\"card-content\">\n                            <h3 style=\"font-size:1.1rem; margin-bottom:0.5rem;\">${c.title}</h3>\n                            <div class=\"card-price\">${c.price_text || '${c.price.toLocaleString()} TL'}</div>\n                            <div class=\"card-meta\">${c.rooms || ''} | ${c.m2 || ''} m² | ${c.loc || ''}</div>\n                        </div>\n                    </div>\n                `).join('');\n                document.getElementById('empty').style.display = 'none';\n            }\n            \n            // Update count display\n            document.getElementById('cnt-top').textContent = out.length + ' / ' + DATA.length;\n                </script>\n\n                <!-- Dashboard Tabs Content -->\n                <div class=\"dashboard-tabs-content\">\n                    <!-- Listings tab -->\n                    <div id=\"tab-listings\" class=\"tab-panel active\">\n                        <!-- Filters already above -->\n                        <div class=\"grid\" id=\"grid\"></div>\n                        <div id=\"empty\" style=\"display: none; text-align: center; padding: 3rem; color: #666;\">İlan bulunamadı</div>\n                        <div id=\"cnt-top\" style=\"color: var(--primary); font-weight: bold; margin: 1rem 0;\"></div>\n                    </div>\n        \n                    <!-- Customers tab -->\n                    <div id=\"tab-customers\" class=\"tab-panel\">\n                        <h3 style=\"margin: 0 0 1rem 0; color: var(--primary);\">Müşteri Takibi</h3>\n                        <table class=\"customer-table\">\n                            <thead>\n                                <tr>\n                                    <th>Müşteri</th>\n                                    <th>Telefon</th>\n                                    <th>E-posta</th>\n                                    <th>Takip Tarihi</th>\n                                    <th>Durum</th>\n                                </tr>\n                            </thead>\n                            <tbody id=\"customer-tbody\">\n                                <!-- Customer rows dynamically added -->\n                            </tbody>\n                        </table>\n                        <div style=\"margin: 1rem 0;\">\n                            <button class=\"btn-small\" onclick=\"addCustomer()\">Müşteri Ekle</button>\n                        </div>\n                    </div>\n        \n                    <!-- Tasks tab -->\n                    <div id=\"tab-tasks\" class=\"tab-panel\">\n                        <h3 style=\"margin: 0 0 1rem 0; color: var(--primary);\">Görev Takibi</h3>\n                        <table class=\"task-table\">\n                            <thead>\n                                <tr>\n                                    <th>Başlık</th>\n                                    <th>Müşteri</th>\n                                    <th>Tarih</th>\n                                    <th>Durum</th>\n                                    <th>İlan</th>\n                                </tr>\n                            </thead>\n                            <tbody id=\"task-tbody\">\n                                <!-- Task rows dynamically added -->\n                            </tbody>\n                        </table>\n                        <div style=\"margin: 1rem 0;\">\n                            <button class=\"btn-small\" onclick=\"addTask()\">Yeni Görev Ekle</button>\n                        </div>\n                    </div>\n                </div>\n\n            </body>\n</html>";

